const cartContainer=document.getElementById("cart-container"),cartTotal=document.getElementById("cart-total");let cart=JSON.parse(localStorage.getItem("cart"))||[];function renderCart(){cartContainer.innerHTML="";let t=0;if(0===cart.length){cartContainer.innerHTML="<h2>Your cart is empty.</h2>",cartTotal.textContent="0";return}cart.forEach((e,r)=>{let a=e.quantity||1;t+=e.price*a;let n=document.createElement("div");n.classList.add("cart-item"),n.innerHTML=`

            <img src="${e.image}" alt="${e.title}">

            <div class="cart-info">

                <h3>${e.title}</h3>

                <p>Price: $${e.price}</p>

                <p>
                    Quantity:

                    <button class="qty-btn decrease">
                        -
                    </button>

                    <span>${a}</span>

                    <button class="qty-btn increase">
                        +
                    </button>
                </p>

                <p>
                    Subtotal:
                    $${(e.price*a).toFixed(2)}
                </p>

                <button class="remove-btn">
                    Remove
                </button>

            </div>

        `,n.querySelector(".increase").addEventListener("click",()=>{e.quantity=a+1,updateCart()}),n.querySelector(".decrease").addEventListener("click",()=>{a>1&&(e.quantity=a-1,updateCart())}),n.querySelector(".remove-btn").addEventListener("click",()=>{cart.splice(r,1),updateCart()}),cartContainer.appendChild(n)}),cartTotal.textContent=t.toFixed(2)}function updateCart(){localStorage.setItem("cart",JSON.stringify(cart)),renderCart()}renderCart();